async function closeChickenCycle(batchId){setBusy(true);setErr("");try{let b=(d.chickenBatches||[]).find(x=>x.id===batchId),dead=(d.chickenMortality||[]).filter(x=>x.batch_id===batchId).reduce((n,x)=>n+Number(x.quantity),0),dressedSales=(d.chickenSales||[]).filter(x=>x.batch_id===batchId&&x.sale_type==="dressed").reduce((n,x)=>n+Number(x.quantity),0),remaining=Number(b.initial_quantity)-dead-(d.chickenMoves||[]).filter(x=>x.batch_id===batchId&&x.move_type==="dressed").reduce((n,x)=>n+Number(x.quantity),0)-dressedSales;if(remaining!==0)throw new Error("The cycle cannot be closed yet. All chickens must be accounted for through mortality or live/dressed sales.");let r=await db.from("sakhelwe_chicken_batches").update({status:"completed",completed_on:today()}).eq("id",batchId);if(r.error)throw r.error;setOk("Chicken cycle completed. Final report is now available.");await load()}catch(e){setErr(e.message)}finally{setBusy(false)}}
